  "root_cause": {
    "category": "dependency_slow",
    "service": "orders",
    "summary": "CPU throttling reduced orders service workers to 1, causing severe slowdown and timeouts that propagated to the gateway."
  },
  "confidence": "high",
  "causal_chain": [
    {
      "claim": "At +59.81s an ops event throttled CPU on the orders service, reducing its worker limit from 16 to 1.",
      "status": "confirmed",
      "cites": [
        "ops-E0001",
        "orders-M000c"
      ]
    },
    {
      "claim": "The worker limit reduction caused orders latency to spike and its request queue to grow, as seen in orders metrics where p99 latency rose from ~1ms to seconds and queue depth increased.",
      "status": "confirmed",
      "cites": [
        "orders-M000c",
        "orders-M000d"
      ]
    },
    {
      "claim": "Slow order processing caused gateway calls to orders to exceed the 2500ms timeout, generating numerous upstream_timeout errors in the gateway logs.",
      "status": "confirmed",
      "cites": [
        "gateway-L00073"
      ]
    },
    {
      "claim": "Gateway upstream_timeout errors appeared as 5xx responses and high latency, which is the user‑visible symptom observed in gateway metrics (err5xx rise and p50/p99 ~2500ms).",
      "status": "confirmed",
      "cites": [
        "gateway-M000d",
        "gateway-M000e"
      ]
    }
  ],
  "alternatives": [
    {
      "category": "config_regression",
      "service": "orders",
      "why_less_likely": "No configuration change is recorded for orders; the observed slowdown aligns with the explicit CPU throttling ops event.",
      "cites": [
        "ops-E0001"
      ]
    },
    {
      "category": "process_crash",
      "service": "orders",
      "why_less_likely": "There is no log indicating orders process restart or crash; instead workers_limit changed gradually and the service stayed up.",
      "cites": [
        "orders-M000b",
        "orders-M000c"
      ]
    }
  ]
